class Solution {
public:
    long long minIncrementOperations(vector<int>& nums, int k) {
        int n = nums.size();
        vector<long long> dp(n);
        for (int i = 0; i < n; ++i) {
            long long best = LLONG_MAX;
            for (int j = 1; j <= 3; ++j)
                best = min(best, i - j >= 0 ? dp[i - j] : 0LL);
            dp[i] = best + max(0LL, (long long)k - nums[i]);
        }
        return min({dp[n-1], dp[n-2], dp[n-3]});
    }
};

